const b = $('Webhook').item.json.body;
const issue = b.issue;
const body = issue.body || '';
// Pick the first agent @-mention (humans mentioned in the same body are
// ignored — only agent mentions trigger this workflow upstream).
const agents = ($env.N8N_AGENT_LOGINS || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const mentions = (body.match(/@([a-zA-Z0-9-]+)/g) || []).map(m => m.slice(1));
const mentionedLogin = mentions.find(m => agents.includes(m.toLowerCase())) || '';
const args = {
  surface: 'issue-body',
  repoOwner: b.repository.owner.login,
  repoName: b.repository.name,
  repoFull: b.repository.full_name,
  senderLogin: b.sender && b.sender.login,
  senderType: b.sender && b.sender.type,
  issueNumber: issue.number,
  issueTitle: issue.title,
  issueBody: body,
  issueUrl: issue.html_url,
  mentionedLogin,
  title: issue.title,
  bodyText: body,
};
// promptB64 is built here so the dispatcher can pass it straight through
// without needing to know the surface's prompt template.
const prompt = `You were @-mentioned by @${args.senderLogin} in the body of issue #${args.issueNumber}.
Repo: ${args.repoFull}. URL: ${args.issueUrl}.

Issue title: ${args.issueTitle}

Issue body:
---
${args.issueBody}
---

Reply conversationally on the issue. Be concise. Ask a clarifying question if ambiguous, or share an opinion if it's a design discussion. Do NOT propose code changes here — for code work, the human can assign you or apply the \`agent-task\` label, which routes through the implementation flow. Markdown supported.

Return ONLY the reply body. No preamble.
`;
args.promptB64 = Buffer.from(prompt, 'utf8').toString('base64');
return [{ json: { argsB64: Buffer.from(JSON.stringify(args), 'utf8').toString('base64') } }];
